WITH flattened AS (SELECT id, level, latency_ms, key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS key, attr_value) SELECT *, MIN(latency_ms) OVER w_running AS key_min_latency_ms, PERCENT_RANK() OVER w_running_2 AS latency_ms_percent_rank, SUM(latency_ms) OVER (PARTITION BY level, key) AS level_sum_latency_ms FROM flattened WINDOW w_running AS (PARTITION BY key, level), w_running_2 AS (ORDER BY latency_ms ASC NULLS FIRST);
